def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    from collections import Counter
    counts=Counter(v for row in grid for v in row)
    bg=counts.most_common(1)[0][0]
    color=next(v for v in counts if v != bg)
    for top in range(h):
      for bot in range(top+2,h):
        for left in range(w):
          for right in range(left+2,w):
            if all(grid[top][c]==color and grid[bot][c]==color for c in range(left,right+1)) and all(grid[r][left]==color and grid[r][right]==color for r in range(top,bot+1)):
              for r in range(top+1,bot):
                for c in range(left+1,right): out[r][c]=4
    return out
